using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private static LoyaltyDiscountQuote Quote(string subtotal, LoyaltyTier tier, string? code = null) =>
        new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(Eur.Cents(subtotal), tier, code));

    private static void AssertQuote(LoyaltyDiscountQuote quote, string discount, string? total)
    {
        Assert.Equal(Eur.Cents(discount), quote.DiscountCents);
        if (total is not null)
        {
            Assert.Equal(Eur.Cents(total), quote.TotalCents);
        }
    }

    // Member receives the loyalty discount of their tier
    [Theory]
    [InlineData(LoyaltyTier.Bronze, "5.00", "95.00")]
    [InlineData(LoyaltyTier.Silver, "10.00", "90.00")]
    [InlineData(LoyaltyTier.Gold, "15.00", "85.00")]
    public void S1_MemberReceivesTheLoyaltyDiscountOfTheirTier(LoyaltyTier tier, string discount, string total) =>
        AssertQuote(Quote("100.00", tier), discount, total);

    // The loyalty discount never exceeds 20.00 EUR
    [Theory]
    [InlineData("200.00", LoyaltyTier.Gold, "20.00", "180.00")]
    [InlineData("300.00", LoyaltyTier.Silver, "20.00", "280.00")]
    [InlineData("120.00", LoyaltyTier.Gold, "18.00", "102.00")]
    public void S2_LoyaltyDiscountNeverExceedsTwentyEuros(string subtotal, LoyaltyTier tier, string discount, string total) =>
        AssertQuote(Quote(subtotal, tier), discount, total);

    // No loyalty discount under a 30.00 EUR subtotal
    [Theory]
    [InlineData("29.99", "0.00", "29.99")]
    [InlineData("30.00", "4.50", "25.50")]
    public void S3_NoLoyaltyDiscountUnderThirtyEuros(string subtotal, string discount, string total) =>
        AssertQuote(Quote(subtotal, LoyaltyTier.Gold), discount, total);

    // The WELCOME5 promo code takes 5.00 EUR off after the loyalty discount
    [Theory]
    [InlineData("100.00", LoyaltyTier.Silver, "15.00", "85.00")]
    [InlineData("20.00", LoyaltyTier.Bronze, "5.00", "15.00")]
    public void S4_Welcome5TakesFiveEurosOffAfterTheLoyaltyDiscount(string subtotal, LoyaltyTier tier, string discount, string total) =>
        AssertQuote(Quote(subtotal, tier, "WELCOME5"), discount, total);

    // The cap applies to the loyalty discount only, never to WELCOME5
    [Theory]
    [InlineData("200.00", LoyaltyTier.Gold, "25.00", "175.00")]
    [InlineData("300.00", LoyaltyTier.Silver, "25.00", "275.00")]
    public void S5_CapAppliesToLoyaltyDiscountOnly(string subtotal, LoyaltyTier tier, string discount, string total) =>
        AssertQuote(Quote(subtotal, tier, "WELCOME5"), discount, total);

    // Promo codes ignore case
    [Theory]
    [InlineData("welcome5")]
    [InlineData("Welcome5")]
    public void S6_PromoCodesIgnoreCase(string code) =>
        AssertQuote(Quote("100.00", LoyaltyTier.Silver, code), "15.00", null);

    // The SUMMER10 promo code takes 10 % off what is left, at most 15.00 EUR
    [Theory]
    [InlineData("100.00", LoyaltyTier.Silver, "19.00", "81.00")]
    [InlineData("300.00", LoyaltyTier.Bronze, "30.00", "270.00")]
    [InlineData("20.00", LoyaltyTier.Gold, "2.00", "18.00")]
    public void S7_Summer10TakesTenPercentOffWhatIsLeft(string subtotal, LoyaltyTier tier, string discount, string total) =>
        AssertQuote(Quote(subtotal, tier, "SUMMER10"), discount, total);

    // An unknown promo code is ignored
    [Fact]
    public void S8_UnknownPromoCodeIsIgnored() =>
        AssertQuote(Quote("100.00", LoyaltyTier.Silver, "SPRING"), "10.00", "90.00");

    // Platinum members receive a 20 % loyalty discount
    [Theory]
    [InlineData("100.00", "20.00", "80.00")]
    [InlineData("50.00", "10.00", "40.00")]
    [InlineData("200.00", "20.00", "180.00")]
    public void S9_PlatinumMembersReceiveTwentyPercent(string subtotal, string discount, string total) =>
        AssertQuote(Quote(subtotal, LoyaltyTier.Platinum), discount, total);

    // The discount never exceeds the subtotal
    [Theory]
    [InlineData("4.00", LoyaltyTier.Bronze, "4.00")]
    [InlineData("3.00", LoyaltyTier.Gold, "3.00")]
    public void S10_DiscountNeverExceedsTheSubtotal(string subtotal, LoyaltyTier tier, string discount) =>
        AssertQuote(Quote(subtotal, tier, "WELCOME5"), discount, "0.00");
}
